+  `${BASE_URL}/en/predictions`,
+  `${BASE_URL}/en/football`,          // NFL / soccer disambiguation common
+  `${BASE_URL}/en/basketball`,
+  `${BASE_URL}/en/baseball`,
+  `${BASE_URL}/en/hockey`,
+  `${BASE_URL}/en/american-football`,
+  `${BASE_URL}/football`,
